import {WORKS,FIELDS,VOCAB,CONFUSIONS} from './data.js';
import {STORAGE_KEY,normalize,shuffle,getWork,answerFor,checkAnswer,defaultStore,sanitizeStore,recordRecall,needsPractice,makeQuiz,quizProgress,finishQuiz,quizScore} from './engine.js';

const root=document.querySelector('#app');
let saved,storageAvailable=true;
try{saved=sanitizeStore(JSON.parse(localStorage.getItem(STORAGE_KEY)));}catch{saved=defaultStore();}
let reviewTab='materials',search='',collectionFilter='all',detailImage=0;
let quizOptions={count:14,timerMinutes:0,alternateViews:false,missed:false};
let quizScreen=saved.quiz?.status==='active'?'active':'setup';
let toastTimer;
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={shuffle:'<path d="M3 6h3c5 0 7 12 12 12h3M17 14l4 4-4 4M3 18h3c2 0 3-2 5-5M14 9c1-2 2-3 4-3h3M17 2l4 4-4 4"/>',zoom:'<path d="M9 3H3v6M15 3h6v6M21 15v6h-6M9 21H3v-6"/>',left:'<path d="m14 6-6 6 6 6"/>',right:'<path d="m10 6 6 6-6 6"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',print:'<path d="M6 8V3h12v5M6 17H3V9h18v8h-3M6 14h12v7H6z"/>'};
const icon=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${paths[name]??''}</svg>`;
const btn=(text,action,cls='secondary-button',extra='')=>`<button type="button" class="${cls}" data-action="${action}" ${extra}>${text}</button>`;
const textButton=(text,action,extra='')=>btn(text,action,'text-button',extra);
function save(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(saved));}catch{storageAvailable=false;}}
function notify(message){document.querySelector('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.setAttribute('role','status');el.textContent=message;document.body.append(el);clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.remove(),3500);}
function route(){const hash=location.hash.slice(1);if(/^work-(?:1[2-9]|2[0-5])$/.test(hash))return {view:'detail',id:Number(hash.slice(5))};return {view:['study','quiz','works','review'].includes(hash)?hash:'study'};}
function go(view){if(location.hash===`#${view}`)render();else location.hash=view;}
function startStudy({focus=saved.focus,filter='all',ids=null,randomize=false}={}){const pool=ids??WORKS.filter(w=>filter!=='missed'||needsPractice(saved,w.id,focus)).map(w=>w.id);saved.focus=focus;saved.study={focus,filter,queue:randomize?shuffle(pool):pool,index:0,revealed:false,typed:'',again:[],correct:0,image:0,ratings:{}};save();}
function study(){if(!saved.study||saved.study.focus!==saved.focus)startStudy();return saved.study;}
function currentStudyWork(){const s=study();return getWork(s.queue[s.index]);}
function recordStudy(correct){const s=study(),w=currentStudyWork();if(!w||!s.revealed)return;recordRecall(saved,w.id,s.focus,correct);s.ratings??={};s.ratings[w.id]=correct;s.correct=Object.values(s.ratings).filter(Boolean).length;s.again=Object.entries(s.ratings).filter(([,v])=>!v).map(([id])=>Number(id));s.index++;s.revealed=false;s.typed='';s.image=0;save();render();document.querySelector('#recall-input')?.focus({preventScroll:true});}
function revealStudy(){const s=study();if(s.index>=s.queue.length)return;s.revealed=true;save();render();document.querySelector('[data-action="study-got"]')?.focus({preventScroll:true});}
function skeleton(content,view){return `<div class="shell"><header class="topbar"><a href="#study" class="brand" aria-label="Art History study"><svg class="brand-mark" viewBox="0 0 32 32" aria-hidden="true"><path d="M3 26h26v-5H3zm5-8h16v-5H8zm5-8h6V5h-6z" fill="currentColor"/></svg><span>Art History</span></a><nav aria-label="Main navigation">${[['study','Study'],['quiz','Quiz'],['works','Works'],['review','Review']].map(([key,label])=>`<a href="#${key}" class="top-link ${view===key||view==='detail'&&key==='works'?'active':''}" ${view===key||view==='detail'&&key==='works'?'aria-current="page"':''}>${label}</a>`).join('')}</nav><span class="collection-label">AP · 12–25</span></header><main id="main" class="workspace"><div class="page">${content}</div></main><footer class="app-footer">${textButton('Sources & settings','sources')}${!storageAvailable?'<span>Storage unavailable; this session will not be saved.</span>':''}</footer></div>`;}
function artPanel(work,imageIndex,{revealed=false,quiz=false}={}){const index=work.images[imageIndex]?imageIndex:0,current=work.images[index];return `<div class="art-panel"><div class="art-stage"><img src="${current.src}" alt="${revealed?esc(`${work.shortName} — ${current.label}`):'Artwork to identify'}" draggable="false" fetchpriority="high">${btn(icon('zoom'),'zoom','image-enlarge',`aria-label="Enlarge artwork" title="Enlarge artwork" data-work="${work.id}" data-image="${index}"`)}</div>${!quiz&&work.images.length>1?`<div class="image-controls"><span>${revealed?esc(current.label):`View ${index+1} of ${work.images.length}`}</span><div class="image-dots" role="group" aria-label="Artwork views">${work.images.map((im,i)=>`<button class="image-dot ${i===index?'active':''}" data-action="image" data-image="${i}" aria-label="View ${i+1}${revealed?': '+esc(im.label):''}" aria-pressed="${i===index}">${i+1}</button>`).join('')}</div></div>`:''}</div>`;}
function factRows(work,fields=['name','material','date','location','artist','culture','context']){return `<dl class="fact-list">${fields.map(field=>`<div class="fact-row ${field==='material'?'featured':''}"><dt>${{name:'Name',material:'Material',date:'Date',location:'Location',artist:'Artist',culture:'Culture',context:'One fact'}[field]}</dt><dd>${esc(answerFor(work,field))}</dd></div>`).join('')}</dl>`;}
function studyView(){
 const s=study(),w=currentStudyWork();
 const toolbar=`<div class="minimal-toolbar"><div class="study-options"><label class="sr-only" for="focus">Study category</label><select id="focus" class="focus-select">${Object.entries(FIELDS).map(([key,val])=>`<option value="${key}" ${key===s.focus?'selected':''}>${val.label}</option>`).join('')}</select><label class="check-row"><input id="missed-only" type="checkbox" ${s.filter==='missed'?'checked':''}> Missed only</label></div><div class="toolbar-actions">${textButton(icon('shuffle'),'shuffle','aria-label="Shuffle study deck" title="Shuffle deck"')}<span class="counter">${Math.min(s.index+1,s.queue.length)} / ${s.queue.length}</span></div></div>`;
 if(!s.queue.length)return toolbar+`<section class="empty-state"><h2>No missed answers</h2>${btn('Study all','study-all','primary-button')}</section>`;
 if(!w){const skipped=s.queue.filter(id=>!Object.hasOwn(s.ratings??{},id));return toolbar+`<section class="empty-state"><h2>Session complete</h2><div class="completion-metrics"><div><strong>${s.correct}</strong><span>Got it</span></div><div><strong>${s.again.length}</strong><span>Again</span></div>${skipped.length?`<div><strong>${skipped.length}</strong><span>Skipped</span></div>`:''}</div><div class="button-row centered">${s.again.length?btn(`Retry ${s.again.length} missed`,'retry-study','primary-button'):btn('Study again','study-all','primary-button')}${skipped.length?btn('Study skipped','study-skipped'):''}${btn('Mock quiz','go-quiz')}</div></section>`;}
 const label=s.focus==='all'?'Identify the work':s.focus==='context'?'One fact':({name:'Name',material:'Material',date:'Date',location:'Location',artist:'Artist',culture:'Culture & period'}[s.focus]);
 let answer;
 if(s.revealed){const check=s.typed.trim()?checkAnswer(w,s.focus,s.typed):null;answer=`<div class="answer-reveal" aria-live="polite">${s.focus!=='name'&&s.focus!=='all'?`<div class="answer-title">${esc(w.shortName)}</div>`:''}${s.focus==='all'?`<div class="all-facts">${factRows(w)}</div>`:`<p class="answer-main">${esc(answerFor(w,s.focus))}</p>`}${check?`<div class="feedback ${check.status==='correct'?'success':check.status==='partial'?'partial':''}">${esc(check.message)}</div>`:''}<details class="memory-details"><summary>${s.focus==='context'?'More facts':'Notes'}</summary>${s.focus==='material'?`<p>${esc(w.cue)}</p>`:''}${s.focus==='context'?`<ul>${[w.function,...w.facts].map(f=>`<li>${esc(f)}</li>`).join('')}</ul>`:w.notes.map(n=>`<p>${esc(n)}</p>`).join('')}<a href="#work-${w.id}">Work ${w.id} · All details</a></details></div>`;}else answer=`<div class="field recall-field"><label for="recall-input" class="sr-only">Your answer</label><textarea id="recall-input" maxlength="3000" placeholder="Your answer" rows="4" spellcheck="false" autocomplete="off">${esc(s.typed)}</textarea></div>`;
 return toolbar+`<section class="study-surface">${artPanel(w,s.image,{revealed:s.revealed})}<div class="recall-panel"><h1 class="recall-heading">${label}</h1>${answer}<div class="recall-bottom">${s.revealed?`<div class="button-row">${btn('Again','study-again')}${btn('Got it','study-got','primary-button')}</div>`:btn(s.typed.trim()?'Check answer':'Reveal','reveal','primary-button','id="reveal-button"')}</div></div></section><div class="study-footer"><div class="button-row">${textButton(icon('left'),'previous-study',`aria-label="Previous artwork" title="Previous artwork" ${s.index===0?'disabled':''}`)}${textButton(icon('right'),'skip-study','aria-label="Skip artwork" title="Skip without scoring"')}</div><span>${Object.values(saved.stats).filter(x=>(x[s.focus]?.streak??0)>=2).length} / 14 recalled twice</span></div>`;
}
function quizSetup(){const q=saved.quiz;const banner=q?.status==='active'?`<div class="saved-banner"><span>Quiz in progress · ${quizProgress(q)} / ${q.questions.length} answered</span><div class="button-row">${btn('Resume','resume-quiz','primary-button')}${textButton('Discard','discard-quiz')}</div></div>`:q?.status==='review'?`<div class="saved-banner"><span>Last quiz · ${quizScore(q).correct} / ${quizScore(q).total}${quizScore(q).pending?' · review pending':''}</span>${btn('Review results','resume-quiz')}</div>`:'';return `<div class="quiz-setup"><header class="compact-heading"><h1>Mock quiz</h1><p class="muted">Name · Material · One other fact</p></header>${banner}<form id="quiz-setup-form" class="section-card"><div class="setup-fields"><div class="field"><label for="quiz-count">Artworks</label><select id="quiz-count">${[14,7,5].map(n=>`<option value="${n}" ${quizOptions.count===n?'selected':''}>${n===14?'All 14':n}</option>`).join('')}</select></div><div class="field"><label for="quiz-timer">Time limit</label><select id="quiz-timer">${[0,10,15,20].map(n=>`<option value="${n}" ${quizOptions.timerMinutes===n?'selected':''}>${n===0?'None':`${n} minutes`}</option>`).join('')}</select></div></div><label class="check-row option-line"><input id="alternate-views" type="checkbox" ${quizOptions.alternateViews?'checked':''}> Include alternate views</label><label class="check-row option-line"><input id="quiz-missed" type="checkbox" ${quizOptions.missed?'checked':''}> Missed works only</label><div class="setup-start">${btn('Start quiz','start-quiz','primary-button')}</div></form></div>`;}
function quizView(){if(quizScreen==='setup'||!saved.quiz)return quizSetup();return saved.quiz.status==='review'?quizResults():quizActive();}
function quizClock(q){const elapsed=Math.max(0,Math.floor(((q.finishedAt??Date.now())-q.startedAt)/1000));const seconds=q.timerMinutes?Math.max(0,q.timerMinutes*60-elapsed):elapsed;return `${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`;}
function quizActive(){const q=saved.quiz,question=q.questions[q.index],w=getWork(question.id),a=q.answers[w.id]??{};return `<div class="quiz-active-header"><h1>Mock quiz</h1><div class="quiz-meta"><span id="quiz-answered">${quizProgress(q)} / ${q.questions.length} answered</span><span id="quiz-clock" aria-label="${q.timerMinutes?'Time remaining':'Elapsed time'}">${quizClock(q)}</span>${textButton(q.timerMinutes?'Exit (timer continues)':'Save & exit','pause-quiz')}</div></div><div class="thin-progress" aria-hidden="true"><span id="quiz-progress" style="width:${quizProgress(q)/q.questions.length*100}%"></span></div><section class="study-surface quiz-surface">${artPanel(w,question.image,{quiz:true})}<div class="recall-panel"><form id="quiz-answer-form" autocomplete="off"><div class="field"><label for="quiz-name">Name</label><input id="quiz-name" name="name" maxlength="3000" value="${esc(a.name)}" spellcheck="false" autocomplete="off"></div><div class="field"><label for="quiz-material">Material</label><textarea id="quiz-material" name="material" maxlength="3000" spellcheck="false" rows="2">${esc(a.material)}</textarea></div><div class="field"><label for="quiz-fact">One other fact</label><textarea id="quiz-fact" name="fact" maxlength="3000" spellcheck="false" rows="3">${esc(a.fact)}</textarea></div></form></div></section><div class="quiz-bottom"><div class="question-map" role="group" aria-label="Quiz questions">${q.questions.map((question,i)=>{const a=q.answers[question.id]??{};return `<button class="question-dot ${i===q.index?'current':''} ${a.name?.trim()&&a.material?.trim()&&a.fact?.trim()?'answered':''}" id="question-dot-${i}" data-action="quiz-jump" data-index="${i}" aria-label="Question ${i+1}" ${i===q.index?'aria-current="step"':''}>${i+1}</button>`;}).join('')}</div><div class="button-row">${btn('Back','quiz-back','secondary-button',q.index===0?'disabled':'')}${q.index===q.questions.length-1?btn('Finish quiz','finish-quiz','primary-button'):btn('Next','quiz-next','primary-button')}</div></div>`;}
function updateQuizAnswer(field,value){const q=saved.quiz;if(!q||q.status!=='active')return;const id=q.questions[q.index].id;q.answers[id]??={name:'',material:'',fact:''};q.answers[id][field]=value;save();const n=quizProgress(q);const counter=document.querySelector('#quiz-answered');if(counter)counter.textContent=`${n} / ${q.questions.length} answered`;const progress=document.querySelector('#quiz-progress');if(progress)progress.style.width=`${n/q.questions.length*100}%`;const a=q.answers[id];document.querySelector(`#question-dot-${q.index}`)?.classList.toggle('answered',!!(a.name.trim()&&a.material.trim()&&a.fact.trim()));}
function beginQuiz(){const ids=quizOptions.missed?WORKS.filter(w=>needsPractice(saved,w.id,'all')).map(w=>w.id):WORKS.map(w=>w.id);if(!ids.length){notify('No missed works yet.');return;}const start=()=>{saved.quiz=makeQuiz({...quizOptions,ids,count:Math.min(quizOptions.count,ids.length)});quizScreen='active';save();render();document.querySelector('#quiz-name')?.focus({preventScroll:true});};if(saved.quiz?.status==='active')confirmDialog('Replace the saved quiz?','Your current answers will be discarded.','Start new quiz',start);else start();}
function finishCurrentQuiz(){const q=saved.quiz;if(!q||q.status!=='active')return;finishQuiz(q);save();render();window.scrollTo({top:0});}
function requestFinish(){const q=saved.quiz,incomplete=q.questions.length-quizProgress(q);if(incomplete)confirmDialog('Finish this quiz?',`${incomplete} artwork${incomplete===1?' has':'s have'} unanswered fields.`,'Finish quiz',finishCurrentQuiz);else finishCurrentQuiz();}
function gradeField(w,key,answer,grade){const label={name:'Name',material:'Material',fact:'Other fact'}[key],reference=key==='fact'?w.goTo:answerFor(w,key),check=key!=='fact'&&answer.trim()?checkAnswer(w,key,answer):null;return `<div class="grade-field"><h4>${label} ${grade===null?'<span class="tag">Review</span>':''}</h4><div class="submitted">${answer.trim()?esc(answer):'—'}</div><div class="correct-answer">${key==='fact'?'<span class="reference-label">Example</span>':''}${esc(reference)}</div>${key==='fact'?`<details><summary>More valid facts</summary><ul>${[w.date,w.location,answerFor(w,'culture'),w.artist,w.function,...w.facts].map(f=>`<li>${esc(f)}</li>`).join('')}</ul></details>`:check&&check.status!=='correct'?`<p class="review-help">${esc(check.message)}</p>`:''}<div class="grade-toggle" role="group" aria-label="Mark ${label.toLowerCase()} for work ${w.id}">${btn('Correct','grade',grade===true?'selected-yes':'',`data-work="${w.id}" data-field="${key}" data-value="true" aria-pressed="${grade===true}" id="grade-${w.id}-${key}-yes" ${saved.quiz.recorded?'disabled':''}`)}${btn('Missed','grade',grade===false?'selected-no':'',`data-work="${w.id}" data-field="${key}" data-value="false" aria-pressed="${grade===false}" id="grade-${w.id}-${key}-no" ${saved.quiz.recorded?'disabled':''}`)}</div></div>`;}
function quizResults(){const q=saved.quiz,score=quizScore(q),missed=q.questions.filter(x=>Object.values(q.grades[x.id]??{}).some(v=>v===false));return `<header class="results-heading"><div><h1>${score.pending?'Review answers':'Quiz results'}</h1><p class="muted">${score.pending?`${score.pending} field${score.pending===1?'':'s'} to review. Other facts are self-marked.`:'1 point each · Name, material, other fact'}</p></div><div class="score-display"><strong>${score.correct}<span> / ${score.total}</span></strong><small>${score.pending?'Confirmed so far':`${Math.round(score.correct/score.total*100)}%`}</small></div></header><div class="results-actions button-row">${score.pending?btn('Next unreviewed','next-unreviewed','primary-button'):!q.recorded?btn('Save result','save-result','primary-button'):btn('Result saved','noop','secondary-button','disabled')}${missed.length?btn(`Practice ${missed.length} missed`,'practice-quiz-missed'):''}${textButton('New quiz','new-quiz')}</div><div class="results-summary">${['name','material','fact'].map(field=>`<div><strong>${q.questions.filter(x=>q.grades[x.id]?.[field]===true).length} / ${q.questions.length}</strong>${{name:'Names',material:'Materials',fact:'Other facts'}[field]}</div>`).join('')}</div><section aria-label="Answer review">${q.questions.map((question,i)=>{const w=getWork(question.id),a=q.answers[w.id]??{},g=q.grades[w.id]??{};return `<article class="result-item" id="result-${w.id}"><div class="result-item-header"><img src="${w.images[question.image].src}" alt="${esc(w.shortName)}" loading="lazy"><div><span class="small muted">${i+1} · Work ${w.id}</span><h2>${esc(w.shortName)}</h2></div></div><div class="grading-grid">${['name','material','fact'].map(key=>gradeField(w,key,a[key]??'',g[key]??null)).join('')}</div></article>`;}).join('')}</section>`;}
function saveQuizResult(){const q=saved.quiz;if(quizScore(q).pending){notify('Review the remaining fields first.');return;}if(q.recorded)return;for(const question of q.questions){const g=q.grades[question.id];recordRecall(saved,question.id,'name',g.name);recordRecall(saved,question.id,'material',g.material);recordRecall(saved,question.id,'context',g.fact);}const score=quizScore(q);saved.history.unshift({date:Date.now(),correct:score.correct,total:score.total});saved.history=saved.history.slice(0,30);q.recorded=true;save();render();notify('Result saved.');}
function collectionView(){const list=WORKS.filter(w=>(collectionFilter==='all'||needsPractice(saved,w.id,'all'))&&normalize(`${w.id} ${w.name} ${w.material} ${w.culture}`).includes(normalize(search)));return `<header class="compact-heading inline-heading"><h1>Works</h1><span class="muted small">${list.length} / 14</span></header><div class="collection-toolbar"><label class="sr-only" for="work-search">Search works</label><input id="work-search" class="search-input" type="search" placeholder="Search works" value="${esc(search)}"><label class="check-row"><input id="collection-missed" type="checkbox" ${collectionFilter==='missed'?'checked':''}> Missed only</label></div><div class="collection-grid">${list.map(w=>`<a class="art-card" href="#work-${w.id}"><div class="card-image"><img src="${w.images[0].src}" alt="${esc(w.shortName)}" loading="lazy"></div><div class="card-info"><div class="card-number"><span>${w.id} · ${w.culture}</span>${needsPractice(saved,w.id,'all')?'<span>Review</span>':''}</div><h2>${esc(w.shortName)}</h2><p>${esc(w.material)}</p></div></a>`).join('')}</div>${!list.length?'<div class="empty-state">No matching works.</div>':''}`;}
function detailView(id){const w=getWork(id);return `<div class="detail-header"><a href="#works" class="back-link">${icon('left')} Works</a>${btn('Study this work','study-work','secondary-button',`data-work="${w.id}"`)}</div><header class="compact-heading"><div class="eyebrow">${w.id} · ${esc(w.culture)}</div><h1>${esc(w.name)}</h1></header><div class="detail-grid">${artPanel(w,detailImage,{revealed:true})}<div>${factRows(w,['material','date','location','artist','culture'])}<dl class="fact-list"><div class="fact-row"><dt>Patron / subject</dt><dd>${esc(w.patron)}</dd></div></dl></div></div><div class="detail-notes"><div class="detail-context"><section><h2>One fact to remember</h2><p>${esc(w.goTo)}</p><h2>Purpose</h2><p>${esc(w.function)}</p></section><section><h2>Recognize it</h2><p>${esc(w.visual)}</p><ul>${w.facts.map(f=>`<li>${esc(f)}</li>`).join('')}</ul></section></div><details class="source-details"><summary>Notes & sources</summary><p><strong>Memory aid:</strong> ${esc(w.cue)}</p>${w.notes.map(n=>`<p>${esc(n)}</p>`).join('')}<p>Course PDF pages: ${w.sources.join(', ')}.</p>${w.links.map(l=>`<p><a href="${esc(l.url)}" target="_blank" rel="noopener noreferrer">${esc(l.title)}</a></p>`).join('')}</details></div>`;}
function reviewView(){const tabs=[['materials','Materials'],['confusions','Compare'],['timeline','Dates'],['facts','Extra facts'],['vocab','Terms']];let content='';
 if(reviewTab==='materials')content=`<div class="table-scroll"><table class="material-table"><thead><tr><th>Work</th><th>Material</th><th>Remember</th></tr></thead><tbody>${WORKS.map(w=>`<tr><td><a href="#work-${w.id}">${w.id} · ${esc(w.shortName)}</a></td><td><strong>${esc(w.material)}</strong></td><td>${esc(w.cue)}</td></tr>`).join('')}</tbody></table></div>`;
 if(reviewTab==='confusions')content=CONFUSIONS.map(g=>`<section class="material-group"><h2>${esc(g.title)}</h2><ul>${g.items.map(i=>`<li>${esc(i)}</li>`).join('')}</ul></section>`).join('');
 if(reviewTab==='timeline')content=[...WORKS].sort((a,b)=>b.sortDate-a.sortDate).map(w=>`<article class="timeline-row"><div class="year">${esc(w.date)}</div><div><h2><a href="#work-${w.id}">${w.id} · ${esc(w.shortName)}</a></h2><p>${esc(w.culture)} · ${esc(w.period)}</p>${w.dateAlternatives?`<p class="small">Slides also use: ${w.dateAlternatives.map(esc).join('; ')}.</p>`:''}</div></article>`).join('');
 if(reviewTab==='facts')content=`<div class="table-scroll"><table class="material-table"><thead><tr><th>Work</th><th>One specific fact</th></tr></thead><tbody>${WORKS.map(w=>`<tr><td><a href="#work-${w.id}">${w.id} · ${esc(w.shortName)}</a></td><td>${esc(w.goTo)}</td></tr>`).join('')}</tbody></table></div>`;
 if(reviewTab==='vocab')content=`<div class="vocab-grid">${VOCAB.map(([term,meaning,example])=>`<section class="vocab-item section-card"><h2>${esc(term)}</h2><p>${esc(meaning)}</p><div class="vocab-example">${esc(example)}</div></section>`).join('')}</div>`;
 return `<header class="compact-heading inline-heading"><h1>Quick review</h1>${textButton(icon('print')+' Print','print')}</header><div class="review-tabs" role="group" aria-label="Review topic">${tabs.map(([key,title])=>btn(title,'review-tab',`chip ${key===reviewTab?'active':''}`,`data-tab="${key}" aria-pressed="${key===reviewTab}"`)).join('')}</div><h1 class="print-heading">AP Art History · Works 12–25 · ${tabs.find(t=>t[0]===reviewTab)[1]}</h1><div class="review-content">${content}</div>`;}
function modal(content,{image=false,onReady=null}={}){document.querySelector('dialog')?.remove();const d=document.createElement('dialog');d.className=`dialog ${image?'image-dialog':''}`;d.innerHTML=`${btn(icon('close'),'close-modal','dialog-close','aria-label="Close dialog"')}${content}`;document.body.append(d);d.addEventListener('click',e=>{if(e.target.closest('[data-action="close-modal"]'))d.close();if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}});d.addEventListener('close',()=>d.remove());d.showModal();onReady?.(d);return d;}
function confirmDialog(title,message,label,onConfirm){modal(`<h2>${esc(title)}</h2><p>${esc(message)}</p><div class="button-row">${btn('Cancel','close-modal')}${btn(esc(label),'confirm','primary-button','id="dialog-confirm"')}</div>`,{onReady:d=>d.querySelector('#dialog-confirm').onclick=()=>{d.close();onConfirm();}});}
function sourcesDialog(){modal(`<h2>Sources & settings</h2><p>Primary source: <em>Unit 2 ANCIENT NEAR EASTERN ART.pdf</em>, works 12–25. Each work lists its PDF pages and supplementary sources.</p><p>Dates and material names follow the course slides. Discrepancies are listed in the work notes.</p><h3>Quiz scoring</h3><p>Names and materials receive a suggested mark. Extra facts are self-marked and must add information beyond the name and material. Adjust marks before saving. Practice scores may differ from a teacher’s grading.</p><h3>Progress</h3><p>Progress is saved only in this browser on this device.</p><div class="settings-actions">${btn('Export progress','export-progress')}${btn('Import progress','import-progress')}<input type="file" id="import-file" accept="application/json,.json" hidden></div><details class="source-details"><summary>Reset progress</summary><p>Clear saved study progress and quizzes on this device.</p>${btn('Reset all progress','reset-progress','danger-button')}</details><details class="source-details"><summary>Image credits</summary><p>Images are extracted from the course PDF; page numbers are recorded in <a href="images/sources.json" target="_blank" rel="noopener">the image manifest</a>. Rights remain with the original image owners.</p></details>`,{onReady:d=>{
 d.querySelector('[data-action="export-progress"]').onclick=()=>{const blob=new Blob([JSON.stringify(saved,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='art-history-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
 d.querySelector('[data-action="import-progress"]').onclick=()=>d.querySelector('#import-file').click();
 d.querySelector('#import-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>2000000){notify('That file is too large.');return;}try{const raw=JSON.parse(await file.text());if(raw.version!==1||typeof raw.stats!=='object')throw new Error();const clean=sanitizeStore(raw);d.close();confirmDialog('Import saved progress?','This replaces progress currently saved on this device.','Import',()=>{saved=clean;quizScreen=saved.quiz?.status==='active'?'active':'setup';save();render();notify('Progress imported.');});}catch{notify('Use an Art History progress export.');}};
 d.querySelector('[data-action="reset-progress"]').onclick=()=>{d.close();confirmDialog('Reset all progress?','Saved sessions, answers, and quiz results will be cleared on this device.','Reset',()=>{saved=defaultStore();quizScreen='setup';save();render();notify('Progress reset.');});};
 }});}
function render(){const r=route();const content=r.view==='study'?studyView():r.view==='quiz'?quizView():r.view==='works'?collectionView():r.view==='detail'?detailView(r.id):reviewView();root.innerHTML=skeleton(content,r.view);document.title=`${r.view==='detail'?getWork(r.id).shortName:{study:'Study',quiz:'Quiz',works:'Works',review:'Review'}[r.view]} · Art History`;}

root.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(!el||el.disabled)return;switch(el.dataset.action){
 case 'reveal':revealStudy();break;
 case 'study-again':recordStudy(false);break;
 case 'study-got':recordStudy(true);break;
 case 'study-all':startStudy({randomize:true});render();break;
 case 'retry-study':{const s=study();startStudy({focus:s.focus,ids:[...new Set(s.again)],randomize:true});render();break;}
 case 'study-skipped':{const s=study();startStudy({focus:s.focus,ids:s.queue.filter(id=>!Object.hasOwn(s.ratings??{},id))});render();break;}
 case 'shuffle':{const s=study();startStudy({focus:s.focus,filter:s.filter,randomize:true});render();break;}
 case 'previous-study':{const s=study();s.index=Math.max(0,s.index-1);s.revealed=false;s.typed='';s.image=0;save();render();break;}
 case 'skip-study':{const s=study();s.index++;s.revealed=false;s.typed='';s.image=0;save();render();break;}
 case 'go-quiz':quizScreen='setup';go('quiz');break;
 case 'image':if(route().view==='detail')detailImage=Number(el.dataset.image);else{study().image=Number(el.dataset.image);save();}render();break;
 case 'zoom':{const w=getWork(el.dataset.work),im=w.images[Number(el.dataset.image)];modal(`<img src="${im.src}" alt="Enlarged artwork">`,{image:true});break;}
 case 'sources':sourcesDialog();break;
 case 'start-quiz':beginQuiz();break;
 case 'resume-quiz':quizScreen='active';render();break;
 case 'discard-quiz':confirmDialog('Discard saved quiz?','Quiz answers will be removed. Study progress will remain.','Discard',()=>{saved.quiz=null;quizScreen='setup';save();render();});break;
 case 'pause-quiz':quizScreen='setup';save();render();break;
 case 'new-quiz':quizScreen='setup';render();break;
 case 'quiz-next':saved.quiz.index=Math.min(saved.quiz.questions.length-1,saved.quiz.index+1);save();render();document.querySelector('#quiz-name')?.focus({preventScroll:true});break;
 case 'quiz-back':saved.quiz.index=Math.max(0,saved.quiz.index-1);save();render();break;
 case 'quiz-jump':saved.quiz.index=Number(el.dataset.index);save();render();break;
 case 'finish-quiz':requestFinish();break;
 case 'grade':{const q=saved.quiz;if(q.recorded)break;q.grades[el.dataset.work][el.dataset.field]=el.dataset.value==='true';const id=el.id;save();render();document.getElementById(id)?.focus({preventScroll:true});break;}
 case 'next-unreviewed':{const q=saved.quiz,question=q.questions.find(x=>Object.values(q.grades[x.id]).some(v=>v===null));if(question){document.getElementById(`result-${question.id}`).scrollIntoView({behavior:'smooth',block:'start'});const key=['name','material','fact'].find(f=>q.grades[question.id][f]===null);document.getElementById(`grade-${question.id}-${key}-yes`)?.focus({preventScroll:true});}break;}
 case 'save-result':saveQuizResult();break;
 case 'practice-quiz-missed':{const q=saved.quiz,ids=q.questions.filter(x=>Object.values(q.grades[x.id]).some(v=>v===false)).map(x=>x.id);startStudy({focus:'all',ids});go('study');break;}
 case 'study-work':startStudy({focus:saved.focus,ids:[Number(el.dataset.work)]});go('study');break;
 case 'review-tab':reviewTab=el.dataset.tab;render();break;
 case 'print':window.print();break;
 }});
root.addEventListener('input',event=>{const el=event.target;if(el.id==='recall-input'){study().typed=el.value;save();document.querySelector('#reveal-button').textContent=el.value.trim()?'Check answer':'Reveal';}if(['quiz-name','quiz-material','quiz-fact'].includes(el.id))updateQuizAnswer(el.name,el.value);if(el.id==='work-search'){search=el.value;render();const input=document.querySelector('#work-search');input.focus();}});
root.addEventListener('change',event=>{const el=event.target;if(el.id==='focus'){startStudy({focus:el.value,filter:study().filter});render();}if(el.id==='missed-only'){startStudy({focus:saved.focus,filter:el.checked?'missed':'all',randomize:el.checked});render();}if(el.id==='collection-missed'){collectionFilter=el.checked?'missed':'all';render();}if(el.id==='quiz-count')quizOptions.count=Number(el.value);if(el.id==='quiz-timer')quizOptions.timerMinutes=Number(el.value);if(el.id==='alternate-views')quizOptions.alternateViews=el.checked;if(el.id==='quiz-missed')quizOptions.missed=el.checked;});
root.addEventListener('submit',event=>event.preventDefault());
document.addEventListener('keydown',event=>{if(document.querySelector('dialog[open]')||event.isComposing)return;if(route().view==='study'&&event.key==='Enter'&&!event.shiftKey){if(event.target.closest('button,select,a'))return;event.preventDefault();if(!study().revealed)revealStudy();else recordStudy(true);}if(route().view==='study'&&!event.target.closest('input,textarea,select,button,a')&&study().revealed){if(event.key==='1')recordStudy(false);if(event.key==='2')recordStudy(true);}});
window.addEventListener('hashchange',()=>{detailImage=0;render();window.scrollTo({top:0});});
document.querySelector('.skip-link').addEventListener('click',event=>{event.preventDefault();const main=document.getElementById('main');main.tabIndex=-1;main.focus();main.scrollIntoView({block:'start'});});
window.addEventListener('beforeunload',save);
setInterval(()=>{const q=saved.quiz;if(!q||q.status!=='active')return;const el=document.querySelector('#quiz-clock');if(el)el.textContent=quizClock(q);if(q.timerMinutes&&Date.now()-q.startedAt>=q.timerMinutes*60000){finishQuiz(q);save();if(route().view==='quiz'){quizScreen='active';render();}notify('Time is up. Answers saved for review.');}},1000);

if(document.modelContext?.registerTool){const lifecycle=new AbortController();const tools=[
 {name:'list_study_works',description:'List the 14 AP Art History works available in this study app.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:()=>({works:WORKS.map(w=>({id:w.id,name:w.name})),count:WORKS.length})},
 {name:'start_study_session',description:'Start study by category and optional work numbers. Replaces the current study session; leaves a saved quiz intact.',inputSchema:{type:'object',properties:{category:{type:'string',enum:Object.keys(FIELDS)},workIds:{type:'array',items:{type:'integer',minimum:12,maximum:25},minItems:1,maxItems:14}},required:['category'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(!input||!Object.hasOwn(FIELDS,input.category)||Object.keys(input).some(k=>!['category','workIds'].includes(k))||(input.workIds!==undefined&&(!Array.isArray(input.workIds)||input.workIds.length===0||input.workIds.length>14||input.workIds.some(id=>!Number.isInteger(id)||!getWork(id)))))throw new Error('Choose a valid category and work numbers 12–25.');startStudy({focus:input.category,ids:input.workIds?[...new Set(input.workIds)]:null});history.replaceState(null,'','#study');render();return {category:saved.focus,works:study().queue.length,view:'study'};}}
 ];for(const tool of tools){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
render();
